mapper.select:
SELECT p.id AS id, c.page_id AS pageId, p.parent_id AS parentId, c.version AS version, c.describe AS describe, c.content AS content, p.title AS title, c.updated_on AS updatedOn, c.mem_id AS memId FROM wiki_page p JOIN wiki_content c ON p.last_ver = c.version AND p.id = c.page_id JOIN wiki w ON w.id = p.wiki_id WHERE w.prj_id = #{id}
AND p.title = #{title}
AND p.title = w.start_page

select count(*)
from wiki_page p
join wiki w
on w.id = p.wiki_id
where w.prj_id = #{id}
and title = #{name}

select p.id, p.title, p.parent_id AS parentId from wiki_page p join wiki i on i.id = p.wiki_id where i.prj_id = #{prjId}
AND p.id NOT IN ( SELECT id FROM wiki_page START WITH id = #{id} CONNECT BY PRIOR id = parent_id )
order by p.title

SELECT COUNT(*)
FROM wiki_page
WHERE parent_id = #{pageId}

mapper.update:
update wiki_page
set parent_id = #{parentId}
where id = #{id}

mapper.select:
SELECT title FROM ( SELECT p.title AS title FROM wiki_page p JOIN wiki w ON w.id = p.wiki_id WHERE w.prj_id = #{projectId}
AND UPPER(p.title) LIKE '%' || UPPER(#{q}) || '%'
ORDER BY p.title ) WHERE ROWNUM <= 20
